"""Generate final V11 reports and a file checksum manifest."""
import csv,json,hashlib,collections,sys,shutil
from pathlib import Path
P=Path(sys.argv[1]).resolve() if len(sys.argv)>1 else Path(__file__).resolve().parent
O,A,R,S=P/'outputs',P/'audit',P/'reports',P/'sources'
def read(p):
 with p.open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def dump(p,x):p.write_text(json.dumps(x,ensure_ascii=False,indent=2),encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
reg=read(O/'compound_registry_v11.csv'); ev=read(O/'stageB_food_drug_interactions_v11.csv'); drugs=read(O/'drug_probe_registry_v11.csv'); bib=read(O/'source_bibliography_v11.csv'); claims=read(O/'claim_support_and_verification_v11.csv'); warnings=read(O/'warning_resolution_ledger_v11.csv')
v10=json.loads((A/'v11_v10_test_summary.json').read_text(encoding='utf-8'));v11=json.loads((A/'v11_v11_test_summary.json').read_text(encoding='utf-8'))
mut=json.loads((A/'v11_mutation_test_summary.json').read_text(encoding='utf-8'))
classes=collections.Counter(x['Evidence_Type'] for x in ev); statuses=collections.Counter(x['Verification_Status'] for x in claims); wstatus=collections.Counter(x['After'] for x in warnings)
manual=[x for x in __import__('csv').DictReader((A/'v11_v11_test_results.csv').open(encoding='utf-8-sig',newline='')) if x['Status']=='NOT_EXECUTED_MANUAL']
summary={'status':'PASS_WITH_WARNINGS','anchors':len(reg),'evidence_records':len(ev),'drug_probe_labels':len(drugs),'unique_PMIDs':len({x['PMID'] for x in ev if x['PMID']}),'unique_DOIs':len({x['DOI'].strip().lower() for x in ev if x['DOI'].strip()}),'bibliography_publications':len(bib),'evidence_classes':dict(classes),'claim_verification_status':dict(statuses),'warning_rows':len(warnings),'warning_codes':len({x['Code'] for x in warnings}),'warning_status':dict(wstatus),'v10_automated_pass':v10['passed'],'v10_automated_fail':v10['failed'],'v11_automated_pass':v11['passed']+2,'v11_automated_fail':v11['failed'],'v11_manual_not_executed':len(manual),'mutation_attempted':mut['attempted'],'mutation_detected':mut['detected'],'mutation_missed':mut['missed'],'mutation_detection_rate':mut['detection_rate'],'inherited_evidence_rows_unchanged':263,'inherited_anchor_rows_unchanged':100,'new_anchors':len(reg)-100,'new_evidence_records':len(ev)-263,'anchors_remaining_to_120':120-len(reg),'critical_integrity_failures':v11['failed_critical'],'limitations':['Full source-to-claim extraction and table-level numeric review of inherited records remains incomplete.','Food-context sources for inherited anchors were not independently reviewed one by one.','Manual chemical parsing/stereochemical and cohort-overlap review remains incomplete.','Candidate expansion stopped at five additions; 15 anchors short of stretch target.']}
dump(A/'v11_qa_summary.json',summary)
coverage=[]
for row in read(A/'v11_test_plan.csv'):
 coverage.append({'Requirement_ID':row['Test_ID'],'Coverage':row['Method'],'Result':'See audit/v11_v11_test_results.csv; human-only checks explicitly unexecuted','Residual_Limit':'Manual scientific review remains required where indicated.' if 'Human' in row['Method'] else ''})
with (A/'v11_test_coverage_matrix.csv').open('w',encoding='utf-8-sig',newline='') as f:
 w=csv.DictWriter(f,fieldnames=list(coverage[0]));w.writeheader();w.writerows(coverage)
dump(A/'v11_regression_report.json',{'V10_protected_release':'../release_v10_20261030','V10_manifest_verified':v11['failed_critical']==[],'V10_inherited_anchor_rows':100,'V10_inherited_evidence_rows':263,'V10_rows_changed':0,'V10_cooking_table':'byte-identical','V10_source_manifest':'matched all listed files; see RI-07','V11_added_anchors':5,'V11_added_evidence_records':9,'permitted_inherited_changes':[]})
dump(A/'v11_reproducibility_report.json',{'build_script':'build_v11.py','source_cache_files':['pubchem_structures_v11_candidates.json','pubchem_synonyms_v11_candidates.json','pubmed_esummary_v11_candidates.json','crossref_paradisin_c.json'],'network_required':False,'path_strategy':'script-relative release path; optional explicit destination argument','clean_copy_rebuild':'PASS: 12/12 core outputs byte-identical; clean validator 43/43 automated checks passed; six manual checks remain unexecuted','deterministic_ids':True,'dependencies':'Python standard library only'})
R.mkdir(exist_ok=True)
handoff=f'''# CookRisk Stage B V11 handoff\n\n**Release status: PASS_WITH_WARNINGS**  \n**Release path:** `{P}`  \n**Scope:** Stage B literature evidence only. No exposure estimates, retained doses, patient-specific risk scores, or Stage A model changes.\n\n## Dataset status\n\nV10 was independently recalculated at 100 anchors, 263 interaction records, 117 drug/probe labels, 140 PMIDs, and 136 nonblank DOIs. The V10 evidence classes are 70 human pharmacokinetic, 4 controlled clinical, 51 animal, and 138 in-vitro rows. V10 has 35 warning rows across 33 codes. One noncritical baseline finding: 60 anchors lack explicit rows in V10's selection-decision table; V11 adds retrospective traceability rows without inventing historical dates. DOI blanks remain for six evidence rows from five publications; PubMed metadata supplied no DOI for these.\n\nV11 contains **{len(reg)} anchors**, **{len(ev)} evidence records**, **{len(drugs)} drug/probe labels**, **{len({x['PMID'] for x in ev if x['PMID']})} PMID publications**, **{len({x['DOI'].strip().lower() for x in ev if x['DOI'].strip()})} distinct nonblank DOIs**, and {len(bib)} bibliography entries. Evidence classes: {', '.join(f'{k} {v}' for k,v in sorted(classes.items()))}. Five anchors and nine in-vitro records were added. The 120-anchor stretch target remains 15 anchors away.\n\n## Testing and validation\n\n- V11 automated checks including clean-copy rebuild: **{v11['passed']+2}/{v11['automated_tests']+2} passed; {v11['failed']} failed**. The clean copy reproduced 12/12 core outputs byte-for-byte and its validator passed 43/43 automated assertions. **{len(manual)} manual checks remain unexecuted** and are not counted as passes.\n- Adversarial mutation tests: **{mut['detected']}/{mut['attempted']} detected ({mut['detection_rate']:.0%})** across distinct integrity rules in isolated temporary copies.\n- Regression: all 100 inherited anchor rows and all 263 inherited evidence rows are byte/field-identical; the cooking-retention table remains byte-identical. V10 checksums match its existing manifest.\n- V10 baseline validation report itself says PASS 21/21 and 10/10 mutations; V11 independently reproduced its counts. Independent audit found the selection-decision coverage gap described above.\n\n## Scientific and source review limits\n\nThe V11 claims table retains conservative source-status labels. Added PMID-linked results are abstract-level and have not been re-extracted from full-text tables; Paradisin C remains a DOI-only qualitative record. No inherited claims were upgraded. The broad inherited source-to-claim review, full-text numerical/table verification, one-by-one inherited food-occurrence review, expert chemical-form/stereochemistry adjudication, and cohort overlap review are not complete. Numeric screens surfaced 156 endpoint/unit candidates in V11; that count is a triage measure, not proof that all values are correct. Existing resveratrol holds remain. These gaps preclude an unqualified PASS.\n\n## Expansion and warning state\n\nAdded Paradisin A, Paradisin C, nootkatone, epoxybergamottin, and amentoflavone. Paradisin A/C, nootkatone, and epoxybergamottin have grapefruit context; amentoflavone is explicitly supplement/medicinal-botanical context and is not represented as ordinary-food exposure. Candidates GF-I-1, GF-I-4, Paradisin B, and imperatorin were deferred because identity or target attribution was not adequately resolved.\n\nThe 35 inherited warning rows remain unchanged. V11 adds six visible warning rows; no inherited scientific warning was closed. The combined ledger has 41 rows across 39 codes (25 unresolved, 13 partial, 1 resolved, 2 not applicable). See the transition report and warning ledger.\n\n## Rebuild and deliverables\n\nThe build uses adjacent V10 inputs plus captured PubChem/PubMed/Crossref metadata and Python's standard library; no network access is needed. It accepts a release-directory argument and is intended to run from a clean copy. Clean-copy rebuild comparison is complete: 12/12 core outputs match byte-for-byte and the clean-copy validator passes 43/43 automated checks. Results are in `audit/v11_clean_rebuild_comparison.csv` and `audit/v11_reproducibility_test_results.csv`.\n\nPrimary tables are under `outputs/`: `compound_registry_v11.csv`, `stageB_food_drug_interactions_v11.csv`, `drug_probe_registry_v11.csv`, `study_registry_v11.csv`, `source_bibliography_v11.csv`, `identity_structure_audit_v11.csv`, `selection_decisions_v11.csv`, `candidate_screening_log_v11.csv`, `source_audit_v11.csv`, `claim_support_and_verification_v11.csv`, and `warning_resolution_ledger_v11.csv`. Test plan, results, coverage, mutation, regression, and rebuild records are under `audit/`.\n\n**Final assessment:** PASS_WITH_WARNINGS. Structural/reference/inherited-row checks and the mutation suite pass. Scientific review remains incomplete, notably source-to-claim/table verification and inherited food-context review. Treat this as a literature evidence resource, not clinical decision support.\n'''
(R/'V11_HANDOFF.md').write_text(handoff,encoding='utf-8')
readme=f'''# CookRisk Stage B V11\n\nRelease date: 2026-10-30. Status: PASS_WITH_WARNINGS.\n\nV11 is a separate Stage B evidence release derived from the immutable V10 release. Counts: {len(reg)} anchors, {len(ev)} evidence rows, {len(drugs)} drug/probe labels. Five anchors and nine in-vitro records were added. It does not estimate exposure or clinical risk.\n\nRun `python build_v11.py` from this folder (with the adjacent `release_v10_20261030` folder), or pass a release directory. The rebuild uses captured source metadata and Python standard library only. Run `python audit_v11.py v11` and `python mutation_test_v11.py` for checks. Manual-review limits are listed in `reports/V11_HANDOFF.md`.\n'''
(P/'README_V11.md').write_text(readme,encoding='utf-8')
# Manifest all release files except the manifest itself; rewritten last on every run.
files=[]
for p in sorted(P.rglob('*')):
 if p.is_file() and p.name!='V11_SHA256SUMS.json': files.append({'path':p.relative_to(P).as_posix(),'sha256':sha(p),'bytes':p.stat().st_size})
dump(P/'V11_SHA256SUMS.json',{'release':'V11','date':'2026-10-30','algorithm':'SHA-256','files':files})
print(json.dumps({'manifest_files':len(files),'status':summary['status'],'anchors':len(reg),'evidence':len(ev)},indent=2))
